    float firstAvgR = aw_s->firstAvgR;
    float rsA = aw_s->rsA;
    float rsB = aw_s->rsB;
    float rsC = aw_s->rsC;
    float rsD = aw_s->rsD;
    float rsE = aw_s->rsE;
    float rsF = aw_s->rsF;
    float rsG = aw_s->rsG;
    float rsH = aw_s->rsH;
    float rsI = aw_s->rsI;
    float rsJ = aw_s->rsJ;
    float rsK = aw_s->rsK;
    float rsL = aw_s->rsL;
    float rsM = aw_s->rsM;
    float rsN = aw_s->rsN;
    float rsO = aw_s->rsO;
    float rsP = aw_s->rsP;
    float rsQ = aw_s->rsQ;
    float rsR = aw_s->rsR;
